const civicsReviewByTopic = new Map(civicsReviewModules.map(module=>[module.key,module]));
const civicsSubject = subjects.find(subject=>subject.id==='civics');
for (const module of civicsReviewModules) {
  civicsSubject.topics.push({
    key:module.key,
    title:module.title,
    term:'上',
    description:module.description,
    questions:module.questions.map(question=>({...question, subject:civicsSubject.id, topic:module.key}))
  });
}
